"use strict";

const EXPECTED_DENIAL_CODES = new Set([
  "ERR_AUTOJS6_NETWORK_DISABLED",
  "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED",
]);

module.exports = function httpDefaultDenialProbe() {
  const http = require("http");
  const agent = new http.Agent({ keepAlive: true, maxSockets: 2 });
  return new Promise((resolve) => {
    let settled = false;
    function finish(code) {
      if (settled) {
        return;
      }
      settled = true;
      if (agent && typeof agent.destroy === "function") {
        agent.destroy();
      }
      resolve({
        ok: EXPECTED_DENIAL_CODES.has(code) && agent.keepAlive === true,
        summary: "http:client/default-denied/" + code + "/agent",
      });
    }

    try {
      const req = http.get("http://127.0.0.1/", { agent, timeout: 1000 });
      req.on("error", (error) => finish(String(error && error.code || "")));
      req.on("timeout", () => {
        req.destroy();
        finish("TIMEOUT");
      });
    } catch (error) {
      finish(String(error && error.code || ""));
    }
  });
};
